function repeatRule(value){
 if(typeof value==='string')value=JSON.parse(value);
 if(!value||!['day','week','month','year'].includes(value.unit)||!Number.isInteger(value.interval)||value.interval<1||value.interval>365)throw Error('Choose a repeat interval from 1 to 365.');
 const anchor=value.anchor;if(typeof anchor!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(anchor)||new Date(anchor+'T12:00:00Z').toISOString().slice(0,10)!==anchor)throw Error('Choose a valid repeat starting date.');
 const rule={unit:value.unit,interval:value.interval,anchor};
 if(rule.unit==='week'){if(!Array.isArray(value.weekdays)||!value.weekdays.length||value.weekdays.some(n=>!Number.isInteger(n)||n<0||n>6))throw Error('Select at least one weekday.');rule.weekdays=[...new Set(value.weekdays)].sort((a,b)=>a-b);}
 if(rule.unit==='month'){if(value.month_day!=='last'&&(!Number.isInteger(value.month_day)||value.month_day<1||value.month_day>31))throw Error('Choose a monthly date from 1 to 31, or the last day.');rule.month_day=value.month_day;}
 return rule;
}
function repeatDue(rule,day){
 if(day<rule.anchor)return false;
 const a=new Date(rule.anchor+'T12:00:00Z'),d=new Date(day+'T12:00:00Z'),days=Math.round((d-a)/86400000);
 if(rule.unit==='day')return days%rule.interval===0;
 if(rule.unit==='week')return Math.floor((days+(a.getUTCDay()+6)%7)/7)%rule.interval===0&&rule.weekdays.includes(d.getUTCDay());
 const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();
 if(rule.unit==='month'){const months=(d.getUTCFullYear()-a.getUTCFullYear())*12+d.getUTCMonth()-a.getUTCMonth();return months%rule.interval===0&&d.getUTCDate()===(rule.month_day==='last'?last:Math.min(rule.month_day,last));}
 return (d.getUTCFullYear()-a.getUTCFullYear())%rule.interval===0&&d.getUTCMonth()===a.getUTCMonth()&&d.getUTCDate()===Math.min(a.getUTCDate(),last);
}
function repeatLabel(rule){
 const name={day:'day',week:'week',month:'month',year:'year'}[rule.unit],base=rule.unit==='day'&&rule.interval===1?'Daily':'Every '+rule.interval+' '+name+(rule.interval===1?'':'s');
 if(rule.unit==='week')return base+' · '+rule.weekdays.map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d]).join(', ');
 if(rule.unit==='month')return base+' · '+(rule.month_day==='last'?'last day':'day '+rule.month_day);
 return base;
}
