 if(b.hours!==undefined){const work_date=date(b.work_date),today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Phoenix',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);if(work_date>today)fail('Record hours already worked only');const hours=num(b.hours,0,24),total_minutes=Math.round(hours*60);if(hours>0&&total_minutes<1)fail('Enter at least one minute of hours');return {work_date,start_time:'',end_date:work_date,end_time:'',break_minutes:0,total_minutes,notes:text(b.notes||'',4000,false)};}
