function phaseSummary(source,events,today){
 const actual=events.filter(e=>!e.cancelled&&e.actual_date&&e.actual_date<=today).sort((a,b)=>b.actual_date.localeCompare(a.actual_date)||calendarPhases.indexOf(b.phase)-calendarPhases.indexOf(a.phase)||b.created_at.localeCompare(a.created_at)||b.id.localeCompare(a.id))[0];
 const start=actual?.actual_date||(source.type==='tray'?source.start_date:null),phase=actual?.phase||source.stage;
 return {...source,phase,phase_start:start,phase_day:start?Math.round((Date.parse(today)-Date.parse(start))/86400000):null,age_days:source.life_start_date?Math.round((Date.parse(today)-Date.parse(source.life_start_date))/86400000):null,current_room_id:actual?.room_id||source.room_id};
}
