const assetsBinding={async fetch(req){const path=new URL(req.url).pathname;const asset=dashboardAssets[path==='/'?'/index.html':path];return asset?new Response(req.method==='HEAD'?null:asset.body.replaceAll('__APP_VERSION__',String(APP_VERSION)),{headers:{'Content-Type':asset.type}}):new Response('Not found',{status:404});}};
// Fail closed before authentication, initialization, or any database call.
function databaseEnabled(env){return env.DATABASE_ACCESS==='enabled';}
export default {
 fetch(req,env){
  if(!databaseEnabled(env)||!env.DB)return new Response(JSON.stringify({error:'Green Acres database access is paused by the owner. No database requests are being made by this deployment.',code:'DATABASE_PAUSED',version:APP_VERSION}),{status:503,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
  return application.fetch(req,{...env,ASSETS:assetsBinding});
 },
 scheduled(event,env,ctx){
  if(!databaseEnabled(env)||!env.DB||env.SCHEDULED_WORK!=='enabled')return;
  return application.scheduled(event,env,ctx);
 }
};
